#!/usr/bin/env node
// lamba test: run your Lamba app the way Lamba TV runs it, headless, and say in plain words what happened.
//   node lamba-test.mjs [my-app] [--quick] [--headed] [--shots <folder>]
// It needs Playwright once, in this folder:
//   npm i -D playwright && npx playwright install chromium
// What it does, for each app folder (one with lamba.json; with none named: the one here, or every folder next to it):
//   1. the check Lamba's server runs on an upload (the same code as lamba-check.mjs), with what to fix
//   2. the app in the real simulator (Lamba's own TV host, the owner's phone with the real settings drawer, a guest's
//      phone, the sealed frame and its content rules, the room's limits), served from this computer: no network, no account
//   3. the TV at 1920 x 1080 and at the old TV size (960 x 540), the owner's phone and one guest's phone (if guests join)
//   4. a tap on the guest's main button, then every settings group in lamba.json, choice by choice, sent to the TV
//   5. errors in any page, problems the room or the sealed frame refused, every SDK message both ways (the simulator's log)
// It writes screenshots and summary.md (and summary.json) to ./lamba-test-shots/ next to this script, prints the
// summary, and ends with exit code 0 when nothing needs fixing, 1 when something does, 2 when it could not run.
//
// Why the simulator is inside this file: so the test runs offline, from your folder, with the exact simulator and SDK
// that this kit was made with (tools/sdk_kit.mjs puts them in SIM below). Inside Lamba's own repository, SIM is empty and
// the files are read from the repository itself.
import { createServer } from "node:http";
import { readFileSync, readdirSync, statSync, existsSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join, resolve, relative, basename, dirname, sep, extname } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";
import { inflateRawSync } from "node:zlib";

const HERE = dirname(fileURLToPath(import.meta.url));
const SIM = "";   // the kit's build puts the simulator and the SDK here: base64 of a deflated JSON { path: base64 }
const args = process.argv.slice(2), flag = f => args.includes(f);
const opt = k => { const i = args.indexOf(k); return i > -1 ? args[i + 1] : null; };
const QUICK = flag("--quick"), HEADED = flag("--headed");
const SHOTS = resolve(opt("--shots") || join(HERE, "lamba-test-shots"));
const named = args.filter((a, i) => !a.startsWith("-") && args[i - 1] !== "--shots");
const wait = ms => new Promise(r => setTimeout(r, ms));
const say = (...a) => console.log(...a);

// ---------- Playwright ----------
let chromium;
try { ({ chromium } = createRequire(join(HERE, "lamba-test.mjs"))("playwright")); }
catch (e) {
  say("lamba test: Playwright is not installed here. Run these two commands in this folder, then run the test again:\n  npm i -D playwright\n  npx playwright install chromium");
  process.exit(2);
}

// ---------- the simulator's files: from this script, or from Lamba's repository ----------
const REPO = SIM ? null : [join(HERE, ".."), HERE].find(d => existsSync(join(d, "shell/sdk/lamba.js")) && existsSync(join(d, "devs/simulator/sim.js")));
if (!SIM && !REPO) { say("lamba test: this copy has no simulator inside it. Get the newest at https://lamba.tv/devs/kit/lamba-test.mjs"); process.exit(2); }
const FILES = SIM ? (() => { const o = JSON.parse(inflateRawSync(Buffer.from(SIM, "base64")).toString("utf8")); for (const k in o) o[k] = Buffer.from(o[k], "base64"); return o; })() : null;
const TYPES = { ".html": "text/html; charset=utf-8", ".js": "text/javascript", ".mjs": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml",
  ".png": "image/png", ".webp": "image/webp", ".jpg": "image/jpeg", ".woff2": "font/woff2", ".ttf": "font/ttf", ".zip": "application/zip", ".mp4": "video/mp4" };
const asked = new Set(), missing = new Set();
function file(p) {   // p: "devs/simulator/sim.js"
  if (FILES) return FILES[p] || null;
  const f = join(REPO, p);
  if (!f.startsWith(REPO + sep) || !existsSync(f) || !statSync(f).isFile()) return null;
  return readFileSync(f);
}
function serve() {
  const server = createServer((q, r) => {
    let p = decodeURIComponent(new URL(q.url, "http://x").pathname).replace(/^\/+/, "");
    if (p === "" || p.endsWith("/")) p += "index.html";
    if (/(^|\/)\.\.?(\/|$)/.test(p)) { r.writeHead(404); r.end(); return; }
    let b = file(p);
    if (!b && !extname(p)) { p += "/index.html"; b = file(p); }
    asked.add(p);
    if (!b) { if (!/favicon/.test(p)) missing.add(p); r.writeHead(404, { "content-type": "text/plain" }); r.end("not found"); return; }
    r.writeHead(200, { "content-type": TYPES[extname(p)] || "application/octet-stream", "cache-control": "no-store" }); r.end(b);
  });
  return new Promise(res => server.listen(0, "127.0.0.1", () => res(server)));
}

// ---------- the app's folder, as a zip (what you would upload) ----------
const SKIP = n => n === "node_modules" || n.startsWith(".") || n === "lamba-test-shots";
function walk(dir) { const out = []; const go = d => { for (const n of readdirSync(d)) { const f = join(d, n); if (SKIP(n)) continue; if (statSync(f).isDirectory()) go(f); else out.push(relative(dir, f).split(sep).join("/")); } }; go(dir); return out.sort(); }
const CRC = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; CRC[n] = c >>> 0; }
const crc = b => { let c = 0xffffffff; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function zipOf(dir, prefix) {
  const parts = [], central = []; let at = 0; const paths = walk(dir);
  for (const rel of paths) {
    const data = readFileSync(join(dir, rel)), name = Buffer.from(prefix + rel, "utf8"), c = crc(data);
    const h = Buffer.alloc(30); h.writeUInt32LE(0x04034b50, 0); h.writeUInt16LE(20, 4); h.writeUInt16LE(0x800, 6); h.writeUInt32LE(c, 14); h.writeUInt32LE(data.length, 18); h.writeUInt32LE(data.length, 22); h.writeUInt16LE(name.length, 26);
    const e = Buffer.alloc(46); e.writeUInt32LE(0x02014b50, 0); e.writeUInt16LE(20, 4); e.writeUInt16LE(20, 6); e.writeUInt16LE(0x800, 8); e.writeUInt32LE(c, 16); e.writeUInt32LE(data.length, 20); e.writeUInt32LE(data.length, 24); e.writeUInt16LE(name.length, 28); e.writeUInt32LE(at, 42);
    parts.push(h, name, data); central.push(e, name); at += 30 + name.length + data.length;
  }
  const cd = Buffer.concat(central), end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(paths.length, 8); end.writeUInt16LE(paths.length, 10); end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(at, 16);
  return Buffer.concat(parts.concat([cd, end]));
}

// ---------- driving the simulator ----------
const rigFrame = (p, rig) => p.frames().find(f => { try { return new URL(f.url()).searchParams.get("rig") === rig && /\/devs\/simulator\/(tv|phone)\.html/.test(f.url()); } catch (e) { return false; } });
async function sealed(p, rig, view, ms) {   // the app's own page inside a rig, in that view
  const end = Date.now() + (ms || 10000);
  while (Date.now() < end) {
    const r = rigFrame(p, rig);
    if (r) for (const f of p.frames()) if (f.parentFrame() === r && f.url() === "about:srcdoc") { const v = await f.evaluate(() => window.Lamba && Lamba.screen && Lamba.screen.view).catch(() => null); if (v === view) return f; }
    await wait(150);
  }
  return null;
}
const until = async (fn, ms) => { const end = Date.now() + (ms || 8000); let v; while (Date.now() < end) { v = await fn().catch(() => null); if (v) return v; await wait(150); } return v; };
const logLines = p => p.evaluate(() => [...document.querySelectorAll("#lines li")].map(l => ({ kind: (l.className.match(/k-(\w+)/) || [])[1] || "", who: (l.querySelector("b") || {}).textContent || "", text: (l.querySelector("span") || {}).textContent || "" }))).catch(() => []);
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40) || "x";

async function testApp(dir, base, browser, n) {
  const m = JSON.parse(readFileSync(join(dir, "lamba.json"), "utf8")), id = basename(dir), out = join(SHOTS, n > 1 ? id : "");
  mkdirSync(out, { recursive: true });
  const R = { app: id, name: m.name || id, check: null, errors: [], problems: [], refused: [], messages: [], settings: [], shots: [], steps: [], notes: [] };
  const step = (ok, text) => { R.steps.push({ ok, text }); say("  " + (ok === true ? "ok  " : ok === false ? "FIX " : "note") + " " + text); };
  const ctx = await browser.newContext({ viewport: { width: 1680, height: 1050 }, deviceScaleFactor: 1 });
  const p = await ctx.newPage();
  p.on("pageerror", e => R.errors.push("a page threw: " + e.message));
  p.on("console", c => { if (c.type() === "error" && !/favicon|fonts\.g|net::ERR|Failed to load resource|Content Security Policy/.test(c.text())) R.errors.push("console error: " + c.text().slice(0, 300)); });
  const shot = async (name, what, el) => { const f = join(out, name + ".png"); try { if (el) await el.screenshot({ path: f }); else await p.screenshot({ path: f }); R.shots.push({ file: relative(SHOTS, f), what }); } catch (e) { R.notes.push("no screenshot of " + what + ": " + e.message.split("\n")[0]); } };
  const tvShot = async (name, what) => { const box = await p.$("#tvScreen"); await shot(name, what, box); };
  // the simulator's log, kept as the test moves from page to page
  let seen = 0;
  const harvest = async () => {
    const L = await logLines(p);
    for (const l of L.slice(seen)) {
      if (l.kind === "problem") (/refused/.test(l.text) ? R.refused : R.problems).push(l.who + ": " + l.text);
      else if (l.kind === "word" || l.kind === "settings") R.messages.push(l.who + ": " + l.text);
    }
    seen = L.length;
  };
  const phoneShot = async (rig, name, what) => { const el = await p.$('figure.sim-phone[data-rig="' + rig + '"] .sim-glass'); if (el) await shot(name, what, el); };

  // 1. open the app as a zip, the way you upload it
  const pl = m.players || {}, guestsN = m.guests ? Math.max(1, Math.min(2, pl.min || 1, pl.max || 1)) : 0;   // two for a game that needs two
  await p.goto(base + "/devs/simulator/" + (guestsN ? "?guests=" + guestsN : ""));
  await p.waitForSelector("#zipBtn", { timeout: 15000 });
  await p.setInputFiles("#zipInput", { name: id + ".zip", mimeType: "application/zip", buffer: zipOf(dir, id + "/") });
  const tv = await sealed(p, "tv", "screen", 15000);
  step(!!tv, tv ? "the TV page runs in Lamba's TV host (view screen)" : "the TV page never said hello: does it load ../../shell/sdk/lamba.js and call Lamba.ready?");
  const drawn = tv && await until(async () => (await logLines(p)).some(l => l.who === "TV" && /^app: drawn/.test(l.text)), 6000);
  if (tv) step(!!drawn, drawn ? "it called Lamba.drawn() and the host faded it in" : "the host never faded the TV page in: call Lamba.drawn() once the page has drawn itself");
  await wait(1200);

  // 2. the check
  const badge = await until(() => p.evaluate(() => { const b = document.getElementById("checkBadge").textContent; return b && b !== "Checking" ? b : null; }), 20000);
  const items = await p.evaluate(() => [...document.querySelectorAll("#checkBody li")].map(l => l.textContent));
  const ready = badge === "Ready to upload";
  R.check = { ready, badge, problems: ready ? [] : items, notes: ready ? items : [] };
  step(ready, ready ? "the check passes (the same check Lamba's server runs)" : "the check found " + items.length + " to fix (below)");
  if (ready && items.some(t => /placeholder clips/.test(t))) R.notes.push("Before you upload: replace the starter's placeholder clips with real clips of your app (clips/<name>.mp4 540 x 920, 6 to 14 s, and clips/<name>-poster.webp).");

  // 3. the screens
  await tvShot("1-tv-1920x1080", "the TV, 1920 x 1080 (shown scaled)");
  await phoneShot("owner", "3-owner-phone", "the owner's phone: a copy of the TV and the controls");
  const owner = await sealed(p, "owner", "controller", 4000);
  if (m.screens && m.screens.phone) step(!!owner, owner ? "the owner's phone runs the phone page (view controller)" : "the owner's phone page did not say hello (view controller)");
  let guest = null;
  if (m.guests) {
    guest = await sealed(p, "g1", "guest", 10000);
    step(!!guest, guest ? (guestsN > 1 ? guestsN + " guests join" : "a guest joins") + " (view guest) and the TV hears of them" : "a guest's phone page did not say hello (view guest)");
    await wait(800);
    await phoneShot("g1", "4-guest-phone", "a guest's phone");
  }
  await shot("5-room", "the whole room: the TV, the owner's phone and the guests, with the log");

  // 4. a guest taps the main button: the biggest button that is on screen and enabled
  if (guest) {
    const before = (await logLines(p)).length;
    const tapped = await guest.evaluate(() => {
      const b = [...document.querySelectorAll("button, [role=button]")].filter(x => !x.disabled && x.offsetWidth > 0 && x.offsetHeight > 0)
        .map(x => ({ x, a: x.getBoundingClientRect().width * x.getBoundingClientRect().height })).sort((a, b) => b.a - a.a)[0];
      if (!b) return null; const r = b.x.getBoundingClientRect(); b.x.click();
      return { label: (b.x.getAttribute("aria-label") || b.x.textContent || "").trim().slice(0, 40), w: Math.round(r.width), h: Math.round(r.height), cy: Math.round(r.top + r.height / 2), vh: innerHeight };
    }).catch(() => null);
    await wait(1500);
    const after = (await logLines(p)).slice(before);
    if (!tapped) step(null, "the guest's page has no button to tap");
    else {
      const sent = after.filter(l => /Lamba\.send/.test(l.text)).length, heard = after.filter(l => /^app: hears|hears /.test(l.text)).length;
      step(sent > 0 ? true : null, "a guest taps their biggest button (\"" + tapped.label + "\", " + tapped.w + " x " + tapped.h + " px): " + (sent ? sent + " message(s) sent, " + heard + " heard" : "no message was sent"));
      if (tapped.w < 44 || tapped.h < 44) step(false, "the guest's main button is smaller than 44 px: make it big, low in the middle, where the thumb rests");
      else if (tapped.cy < tapped.vh * 0.4) step(null, "the guest's main button sits in the top part of the phone: the thumb rests low in the middle (design rules)");
      await phoneShot("g1", "4-guest-after-tap", "the guest's phone after the tap");
      await tvShot("1-tv-after-guest-tap", "the TV after the guest's tap");
    }
  }

  // the remote's OK button, for an app that asks for it
  if (m.remote && m.remote.ok) {
    const before = (await logLines(p)).length;
    await p.dispatchEvent("#okBtn", "pointerdown"); await wait(250); await p.dispatchEvent("#okBtn", "pointerup"); await wait(1200);
    const keyed = (await logLines(p)).slice(before).some(l => /key/.test(l.text));
    step(keyed ? true : null, "the remote's OK button: " + (keyed ? "the TV page heard it (Lamba.onKey)" : "pressed; nothing in the log said the app heard it"));
    await tvShot("1-tv-after-remote-ok", "the TV after the remote's OK button");
  }

  // 5. the old TV size
  await p.click('[data-tv="old"]'); await wait(2200);
  const oldTv = await sealed(p, "tv", "screen", 8000);
  step(!!oldTv, oldTv ? "the TV page runs at the old TV size, 960 x 540" : "the TV page did not start at the old TV size");
  await tvShot("2-tv-960x540", "the TV at the old TV size, 960 x 540");
  await p.click('[data-tv="hd"]'); await wait(1500);

  // 6. every settings group of lamba.json, choice by choice, sent to the TV
  const groups = ((m.settings || {}).groups || []).filter(g => g && g.key && Array.isArray(g.parts));
  for (const g of QUICK ? groups.slice(0, 1) : groups) {
    for (const part of g.parts.slice(0, QUICK ? 1 : 6)) {
      const pk = part.setting || part.app; if (!pk) continue;
      await harvest();
      // with the guests still in the room, so the TV shows the app in use (not the full join card) as each choice lands
      await p.goto(base + "/devs/simulator/?app=local" + (guestsN ? "&guests=" + guestsN : "") + "&g=" + encodeURIComponent(g.key) + "&p=" + encodeURIComponent(pk));
      seen = 0;
      const host = await until(async () => rigFrame(p, "owner"), 10000);
      await sealed(p, "tv", "screen", 10000); await wait(1200);
      const before = (await logLines(p)).length;
      const label = g.label + (g.parts.length > 1 ? ", " + part.label : "");
      if (!host) { step(false, "settings " + label + ": the owner's phone did not open"); continue; }
      if (part.app) {
        const pf = await sealed(p, "owner", "part", 8000);
        step(!!pf, "settings " + label + ": the app draws this part itself (view part)" + (pf ? "" : ", but it never said hello"));
        await phoneShot("owner", "6-settings-" + slug(g.key) + "-" + slug(pk), "settings: " + label + " on the owner's phone");
        R.settings.push({ group: g.key, part: pk, choices: [], app: true, ok: !!pf });
        continue;
      }
      const field = ((m.settings || {}).fields || {})[pk] || {};
      const n2 = await host.evaluate(() => document.querySelectorAll(".ctl-strip button").length).catch(() => 0);
      const tried = [];
      const count = Math.min(n2, QUICK ? 2 : 8);
      for (let i = 0; i < count; i++) {
        const name = await host.evaluate(i => { const b = document.querySelectorAll(".ctl-strip button")[i]; if (!b) return null; b.click(); return b.getAttribute("aria-label") || b.textContent.trim(); }, i).catch(() => null);
        if (name === null) break;
        await wait(350);
        await host.evaluate(() => { const s = [...document.querySelectorAll("button")].find(b => /Send to TV/i.test(b.textContent) && b.offsetWidth > 0 && !b.disabled); if (s) s.click(); }).catch(() => {});
        await wait(900);
        tried.push(name);
        if (i === 0 || i === count - 1) await tvShot("6-settings-" + slug(g.key) + "-" + slug(pk) + "-" + slug(name), "settings: " + label + ", " + name + ", on the TV");
      }
      if (!n2) await phoneShot("owner", "6-settings-" + slug(g.key) + "-" + slug(pk), "settings: " + label + " on the owner's phone (" + (field.type || "?") + ")");
      const sent = (await logLines(p)).slice(before).filter(l => l.kind === "settings" && /sent to the TV/.test(l.text)).length;
      R.settings.push({ group: g.key, part: pk, type: field.type || "", choices: tried, sent });
      step(n2 ? sent > 0 : null, "settings " + label + ": " + (n2 ? tried.length + " choice(s) tried (" + tried.join(", ") + "), " + sent + " sent to the TV" : "a " + (field.type || "control") + " (screenshot only: the test taps pictures, not dials or fields)"));
    }
  }

  // 7. what the log says: problems, refusals, every SDK message
  await harvest();
  R.errors = [...new Set(R.errors)]; R.problems = [...new Set(R.problems)]; R.refused = [...new Set(R.refused)];
  await ctx.close();
  return R;
}

function summary(all) {
  const L = ["# lamba test", "", "Ran " + new Date().toISOString().replace("T", " ").slice(0, 19) + " UTC. Screenshots are in this folder: open them and look before you change anything.", ""];
  let good = true;
  for (const R of all) {
    const fixes = (R.check && !R.check.ready ? R.check.problems.length : 0) + R.errors.length + R.problems.length + R.refused.length + R.steps.filter(s => s.ok === false).length;
    if (fixes) good = false;
    L.push("## " + R.name + " (" + R.app + "): " + (fixes ? fixes + " to fix" : "nothing to fix"), "");
    L.push("### Steps", ""); R.steps.forEach(s => L.push("- " + (s.ok === true ? "ok: " : s.ok === false ? "FIX: " : "note: ") + s.text)); L.push("");
    if (R.check) {
      L.push("### The check (" + R.check.badge + ")", "");
      (R.check.ready ? R.check.notes : R.check.problems).forEach(t => L.push("- " + t)); L.push("");
    }
    if (R.errors.length) { L.push("### Errors in a page", ""); R.errors.forEach(t => L.push("- " + t)); L.push(""); }
    if (R.problems.length) { L.push("### Problems the simulator logged", ""); R.problems.forEach(t => L.push("- " + t)); L.push(""); }
    if (R.refused.length) { L.push("### Refused by the room or the host", ""); R.refused.forEach(t => L.push("- " + t)); L.push(""); }
    if (R.notes.length) { L.push("### Notes", ""); R.notes.forEach(t => L.push("- " + t)); L.push(""); }
    L.push("### Screenshots", ""); R.shots.forEach(s => L.push("- " + s.file + ": " + s.what)); L.push("");
    L.push("### SDK messages (" + R.messages.length + ", the first 60)", ""); R.messages.slice(0, 60).forEach(t => L.push("- " + t)); L.push("");
  }
  if (missing.size) { L.push("### Inside the test", "", "- the simulator asked for files this copy of lamba-test.mjs does not have: " + [...missing].join(", ") + ". Get the newest at https://lamba.tv/devs/kit/lamba-test.mjs", ""); }
  L.push(good ? "Result: nothing to fix. Next: replace placeholder clips if you still have them, then upload." : "Result: fix what is marked FIX and what is listed above, then run node lamba-check.mjs and node lamba-test.mjs again.");
  return { text: L.join("\n") + "\n", good };
}

// ---------- the command ----------
let dirs = named.map(a => resolve(a));
if (!dirs.length) {
  const here = process.cwd();
  dirs = existsSync(join(here, "lamba.json")) ? [here] : readdirSync(here).filter(n => !SKIP(n) && existsSync(join(here, n, "lamba.json"))).map(n => join(here, n));
  if (!dirs.length) { say("lamba test: no app here. Run it with your app's folder: node lamba-test.mjs my-app"); process.exit(2); }
}
for (const d of dirs) if (!existsSync(join(d, "lamba.json"))) { say("lamba test: " + d + " has no lamba.json (choose your app's own folder)"); process.exit(2); }
rmSync(SHOTS, { recursive: true, force: true }); mkdirSync(SHOTS, { recursive: true });
const server = await serve(), base = "http://127.0.0.1:" + server.address().port;
let browser;
try { browser = await chromium.launch({ headless: !HEADED }); }
catch (e) { say("lamba test: Chromium is not installed for Playwright. Run: npx playwright install chromium\n  (" + e.message.split("\n")[0] + ")"); server.close(); process.exit(2); }
const all = [];
try {
  for (const d of dirs) { say("lamba test: " + basename(d)); all.push(await testApp(d, base, browser, dirs.length)); }
} catch (e) { say("lamba test: the test stopped: " + (e && e.message ? e.message.split("\n")[0] : e)); await browser.close(); server.close(); process.exit(2); }
await browser.close(); server.close();
const s = summary(all);
writeFileSync(join(SHOTS, "summary.md"), s.text);
writeFileSync(join(SHOTS, "summary.json"), JSON.stringify({ good: s.good, apps: all, missing: [...missing] }, null, 1) + "\n");
say("\n" + s.text + "\nWritten: " + relative(process.cwd(), join(SHOTS, "summary.md")) + " and " + all.reduce((n, R) => n + R.shots.length, 0) + " screenshots in " + (relative(process.cwd(), SHOTS) || "."));
if (process.env.LAMBA_TEST_ASKED) writeFileSync(process.env.LAMBA_TEST_ASKED, [...asked].sort().join("\n") + "\n");
process.exit(s.good ? 0 : 1);
